INSERT INTO changelog (title, body, created_at) VALUES ('Сайти — тільки Claude Code', 'Усі сайти клієнтів робимо в Claude Code: у вкладці «Сайт» більше нема вибору платформи (Tilda, Shopify тощо) — скрізь показується «Claude Code». Старий вибір платформи ігнорується. Додано поле «Репозиторій (GitHub)» і кнопку GitHub у шапці сайту. Джері: не пропонувати конструктори сайтів, сайт = код у Claude Code.', datetime('now'));
